import * as T from '../vendor/three.module.js';
// Authored ramps; reconstruction-inspired multiply/add, no Sega data or shader copy.
export function palettePair(material,{lit='#fff3cd',shade='#5966a1',add='#261407'}={}){
 const direction={value:new T.Vector3(-.45,.8,.6)},bypass={value:0},table=new Uint8Array(256*2*4),lookup=new T.DataTexture(table,256,2,T.RGBAFormat);lookup.minFilter=lookup.magFilter=T.NearestFilter;
 function update(a=lit,b=shade,c=add,neutral=false){const hi=new T.Color(a).convertSRGBToLinear(),lo=new T.Color(b).convertSRGBToLinear(),glow=new T.Color(c).convertSRGBToLinear();for(let i=0;i<256;i++){const t=i/255,v=hi.clone().lerp(lo,t),g=glow.clone().multiplyScalar((1-t)**8);if(neutral){v.setRGB(1,1,1);g.setRGB(0,0,0);}for(const [row,color] of [[0,v],[1,g]])table.set([Math.round(color.r*255),Math.round(color.g*255),Math.round(color.b*255),255],(row*256+i)*4);}lookup.needsUpdate=true;}
 const enabled={value:1},gain={value:1},contrast={value:.7},previous=material.onBeforeCompile,key=material.customProgramCacheKey();update();material.onBeforeCompile=s=>{previous(s);s.uniforms.pairEnabled=enabled;s.uniforms.pairGain=gain;s.uniforms.pairContrast=contrast;s.uniforms.pairDirection=direction;s.uniforms.pairBypass=bypass;s.uniforms.pairTable={value:lookup};s.vertexShader='uniform vec3 pairDirection;uniform float pairContrast;uniform sampler2D pairTable;varying vec3 pairDiffuse;varying vec3 pairAdd;\n'+s.vertexShader;s.vertexShader=s.vertexShader.replace('#include <project_vertex>',`vec3 key=normalize((viewMatrix*vec4(pairDirection,0.0)).xyz);float index=clamp(.5-.5*dot(normalize(transformedNormal),key),0.0,1.0);index=mix(index,smoothstep(.08,.92,index),pairContrast);float u=(floor(index*255.0)+.5)/256.0;pairDiffuse=texture2D(pairTable,vec2(u,.25)).rgb;pairAdd=texture2D(pairTable,vec2(u,.75)).rgb;
 #include <project_vertex>`);s.fragmentShader='uniform float pairEnabled;uniform float pairGain;uniform float pairBypass;varying vec3 pairDiffuse;varying vec3 pairAdd;\n'+s.fragmentShader;s.fragmentShader=s.fragmentShader.replace('gl_FragColor = vec4( outgoingLight, diffuseColor.a );','outgoingLight=mix(outgoingLight,mix((diffuseColor.rgb*pairDiffuse+pairAdd)*pairGain,diffuseColor.rgb,pairBypass),pairEnabled);gl_FragColor = vec4( outgoingLight, diffuseColor.a );');};material.customProgramCacheKey=()=> key+'-authored-palette-pair-volume-v3';return {direction,bypass,enabled,gain,contrast,update,table};
}
